import React from 'react';
import { Badge, Banner, Button, Card, Checkbox, DatePicker, Grid, Input, Select, Stack, Table, Tabs, Text, Textarea } from '@oods/components-react';
import '@oods/component-styles/css';

export interface GeneratedUIActions {
  /* @oods-domain-action handleActivate sha256:132ae5872edea21edb7c42dca8b9a68f2fe273e96a2582f29bb159ab5ba3eb4e */
  /* @oods-domain-source sha256:74078086ce732603d310a845ec05eee2e1c8cac3854e52ddb601e0894fdac83b */
  handleActivate: () => void;
  /* @oods-domain-action handleRowActivate sha256:4060ddabfce1a7bc6e2720fc2d17d5cde56c6cb4d9c43f9f47e9728b3ccbfe0e */
  /* @oods-domain-source sha256:8516e83e61fdcf49868b1913db6cfbfb3fa947fbdc4af954641ea508a5d0fafa */
  handleRowActivate: (rowId: string) => void;
  /* @oods-domain-action handleSecondaryActivate sha256:cf2abf20a4a9439def0124269cd8bf7d436d950bd77ec1993d4371a768f926fa */
  /* @oods-domain-source sha256:8c09b14ec8655b63683a812f5281a6ec3734c98b2a0501234d3bfb18507c62fc */
  handleSecondaryActivate: () => void;
}

export interface GeneratedUIProps {
  actions: GeneratedUIActions;
}

type BadgeProps = React.ComponentPropsWithoutRef<typeof Badge>;
type BannerProps = React.ComponentPropsWithoutRef<typeof Banner>;
type ButtonProps = React.ComponentPropsWithoutRef<typeof Button>;
type CardProps = React.ComponentPropsWithoutRef<typeof Card>;
type CheckboxProps = React.ComponentPropsWithoutRef<typeof Checkbox>;
type DatePickerProps = React.ComponentPropsWithoutRef<typeof DatePicker>;
type GridProps = React.ComponentPropsWithoutRef<typeof Grid>;
type InputProps = React.ComponentPropsWithoutRef<typeof Input>;
type SelectProps = React.ComponentPropsWithoutRef<typeof Select>;
type StackProps = React.ComponentPropsWithoutRef<typeof Stack>;
type TableProps = React.ComponentPropsWithoutRef<typeof Table>;
type TabsProps = React.ComponentPropsWithoutRef<typeof Tabs>;
type TextProps = React.ComponentPropsWithoutRef<typeof Text>;
type TextareaProps = React.ComponentPropsWithoutRef<typeof Textarea>;

export const GeneratedUI: React.FC<GeneratedUIProps> = ({ actions }) => {
  if (!actions || !Object.prototype.hasOwnProperty.call(actions, 'handleActivate') || typeof actions.handleActivate !== 'function') { throw new Error('GeneratedUI requires actions.handleActivate.'); }
  if (!actions || !Object.prototype.hasOwnProperty.call(actions, 'handleRowActivate') || typeof actions.handleRowActivate !== 'function') { throw new Error('GeneratedUI requires actions.handleRowActivate.'); }
  if (!actions || !Object.prototype.hasOwnProperty.call(actions, 'handleSecondaryActivate') || typeof actions.handleSecondaryActivate !== 'function') { throw new Error('GeneratedUI requires actions.handleSecondaryActivate.'); }

  /* @oods-domain-binding handleActivate */ const handleActivate = () => { actions.handleActivate(); };
  const [handleDismissState, setHandleDismissState] = React.useState<boolean>(true);
  /* @oods-local-binding handleDismiss */ const handleDismiss = () => { setHandleDismissState(false); };
  const [handleEmailChangeState, setHandleEmailChangeState] = React.useState<string>('invalid');
  /* @oods-local-binding handleEmailChange */ const handleEmailChange = (event: React.ChangeEvent<HTMLInputElement>) => { setHandleEmailChangeState(event.currentTarget.value); };
  const [handleMarketingChangeState, setHandleMarketingChangeState] = React.useState<boolean>(true);
  /* @oods-local-binding handleMarketingChange */ const handleMarketingChange = (event: React.ChangeEvent<HTMLInputElement>) => { setHandleMarketingChangeState(event.currentTarget.checked); };
  const [handleNotesChangeState, setHandleNotesChangeState] = React.useState<string>('Call before renewal.');
  /* @oods-local-binding handleNotesChange */ const handleNotesChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => { setHandleNotesChangeState(event.currentTarget.value); };
  const [handlePlanChangeState, setHandlePlanChangeState] = React.useState<string>('pro');
  /* @oods-local-binding handlePlanChange */ const handlePlanChange = (event: React.ChangeEvent<HTMLSelectElement>) => { setHandlePlanChangeState(event.currentTarget.value); };
  const [handleRenewalChangeState, setHandleRenewalChangeState] = React.useState<string>('2026-09-30');
  /* @oods-local-binding handleRenewalChange */ const handleRenewalChange = (event: React.ChangeEvent<HTMLInputElement>) => { setHandleRenewalChangeState(event.currentTarget.value); };
