  /* @oods-domain-binding handleSecondaryActivate */ const handleSecondaryActivate = () => { actions.handleSecondaryActivate(); };
  const [handleTabChangeState, setHandleTabChangeState] = React.useState<string>('overview');
  /* @oods-local-binding handleTabChange */ const handleTabChange = (selectedId: string) => { setHandleTabChangeState(selectedId); };

  return (
    <>
      <Stack id="foundation-v1-showcase" data-oods-component="Stack" direction="column" gap="lg">
            <Text id="showcase-title" data-oods-component="Text" as="h1" content="Foundation v1 account operations" size="lg" weight="semibold" />
            <Badge id="showcase-status" data-oods-component="Badge" content="Past due" emphasis="solid" icon="!" tone="critical" />
            {handleDismissState && (
