            <Checkbox id="marketing" data-oods-component="Checkbox" help="Choose whether to subscribe." label="Product updates" required checked={handleMarketingChangeState} onChange={handleMarketingChange} />
            <DatePicker id="renewal" data-oods-component="DatePicker" label="Renewal date" max="2026-12-31" min="2026-09-01" step={1} value={handleRenewalChangeState} onChange={handleRenewalChange} />
            <Grid id="showcase-grid" data-oods-component="Grid" align="stretch" gap="md" minColumnWidth="14rem">
                    <Text id="showcase-grid-primary" data-oods-component="Text" as="strong" content="Account health" />
                    <Text id="showcase-grid-secondary" data-oods-component="Text" as="span" content="Recent changes" />
                  </Grid>
            <Input id="email" data-oods-component="Input" help="Use a work address." label="Email" required type="email" validation={{"state":"error","message":"Enter a valid email."}} value={handleEmailChangeState} onChange={handleEmailChange} />
            <Select id="plan" data-oods-component="Select" label="Plan" options={[{"value":"basic","label":"Basic"},{"value":"pro","label":"Pro"},{"value":"enterprise","label":"Enterprise"}]} value={handlePlanChangeState} onChange={handlePlanChange} />
            <Table id="showcase-subscriptions" data-oods-component="Table" caption="Subscriptions" columns={[{"key":"name","label":"Name"},{"key":"plan","label":"Plan"},{"key":"status","label":"Status"}]} density="compact" rows={[{"id":"sub-1","name":"Northwind","plan":"Enterprise","status":"Active"},{"id":"sub-2","name":"Contoso","plan":"Pro","status":"Past due"}]} selectable onRowActivate={handleRowActivate} />
            <Tabs id="showcase-tabs" data-oods-component="Tabs" ariaLabel="Account sections" items={[{"id":"overview","label":"Overview","panel":"Account health and recent changes."},{"id":"billing","label":"Billing","panel":"Invoices and payment methods."},{"id":"security","label":"Security","panel":"Security settings.","disabled":true}]} overflowLabel="More sections" size="md" selectedId={handleTabChangeState} onChange={handleTabChange} />
            <Textarea id="notes" data-oods-component="Textarea" help="Visible to account managers." label="Notes" rows={4} value={handleNotesChangeState} onChange={handleNotesChange} />
          </Stack>
    </>
  );
};

